CL('discharge','ICU discharge checklist','ICU general','NICE CG50 / standard handover practice','lit',{
'Steps':['Discharge criteria met (stable off support)','Lines not required removed','Handover written & verbal (diagnoses, plan, pending tests)','Medication changes communicated','Follow-up plan / outreach review','Family informed']});
CL('neutropenic','Febrile neutropenia checklist','Infection','IDSA 2010 (Freifeld AG et al.); ESMO 2016','lit',{
'Steps':['Blood cultures (peripheral + each CVC lumen)','Antipseudomonal β-lactam within 60 min','MASCC/CISNE risk scored','Add vancomycin if line infection, skin/soft tissue, pneumonia, hemodynamic instability','Antifungal if persistent fever >4–7 days','G-CSF consideration']});
CL('sah','Aneurysmal SAH checklist','Neurology','Based on book Ch 27 Subarachnoid Hemorrhage (p.223–228) + AHA/ASA 2023','book+lit',{
'Steps':['Grade: WFNS / Hunt-Hess; Modified Fisher','SBP <160 until aneurysm secured','Nimodipine 60 mg q4h × 21 d','Early aneurysm securing (coil/clip)','EVD for hydrocephalus','Euvolemia; avoid hyponatremia','TCD / monitoring for delayed cerebral ischemia days 3–14','Seizure prophylaxis only short-term if used']});
CL('tbi','Severe TBI checklist','Neurology','Based on book Ch 65 & 31 + Brain Trauma Foundation 4th ed. 2016','book+lit',{
'Steps':['Avoid hypoxia (SpO2 >94%) and hypotension (SBP ≥100–110)','Head of bed 30°, neck neutral, ETT ties loose','ICP monitoring if GCS ≤8 + abnormal CT','ICP <22 mmHg; CPP 60–70','Osmotherapy (mannitol/hypertonic saline) for raised ICP','PaCO2 35–40 (brief hyperventilation only as rescue)','Normothermia, glucose control, seizure prophylaxis 7 d','Neurosurgical consult']});
